import{_ as t,o as r,c as l,a2 as e}from"./chunks/framework.mRCPFc5l.js";const q=JSON.parse('{"title":"种族总览","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族总览.md","filePath":"表层/种族总览.md","lastUpdated":null}'),o={name:"表层/种族总览.md"};function i(n,a,s,h,d,u){return r(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="种族总览" tabindex="-1">种族总览 <a class="header-anchor" href="#种族总览" aria-label="Permalink to &quot;种族总览&quot;">​</a></h1><h2 id="人-的概念" tabindex="-1">&quot;人&quot;的概念 <a class="header-anchor" href="#人-的概念" aria-label="Permalink to &quot;&quot;人&quot;的概念&quot;">​</a></h2><p>当前世界的所有智慧生灵都被纳入统一的称呼范畴——<strong>&quot;人&quot;</strong>。&quot;人&quot;指拥有高级思考能力与复杂感情的、可双足直立行走的生灵。</p><p>这一概念由神明统一赋予：在此基础上，根据外貌特征加前缀命名，如鹿人、熊人。这一举措打破了种族隔阂，赋予不同生灵统一的身份认同。</p><h2 id="种族大类" tabindex="-1">种族大类 <a class="header-anchor" href="#种族大类" aria-label="Permalink to &quot;种族大类&quot;">​</a></h2><p>当前世界的智慧生灵可分为两大核心大类，另有若干独立种族与传说种。</p><h3 id="羽族" tabindex="-1">羽族 <a class="header-anchor" href="#羽族" aria-label="Permalink to &quot;羽族&quot;">​</a></h3><p>体格普遍偏小，骨骼轻盈且强度极高，部分分支背后生有双翅，具备飞行能力。其下分为三族：</p><ul><li><strong>鹰族</strong>：羽族中体格最健壮，羽毛颜色偏深棕。</li><li><strong>鸽族</strong>：羽族中体格偏小，羽毛多为洁净的白色。</li><li><strong>鹤族</strong>：羽族中体质最弱小，羽毛以白为主、黑为辅；飞行高度与耐力最佳。</li></ul><h3 id="兽族" tabindex="-1">兽族 <a class="header-anchor" href="#兽族" aria-label="Permalink to &quot;兽族&quot;">​</a></h3><p>大陆数量最多的种族大类，为典型福瑞形态，包含多个种族。</p><ul><li><strong>狼族</strong>：兽族中较为新兴的种族，体格中等，看起来有点傻傻的，但作为新兴的主族，其实力不可小觑。</li><li><strong>鹿族</strong>：兽族中历史悠久的种族，体格中等，头有鹿角，充满好奇心与探索欲，作为老牌主族，底蕴深厚。</li><li><strong>熊族</strong>：兽族中历史悠久的种族，体格健壮，多是实干家，工业实力强劲，作为老牌主族，底蕴深厚。</li><li><strong>兔族</strong>：兽族中较为新兴的种族，体格偏小，多居住于林中，整体较为松散，喜欢平静的生活。</li><li><strong>狐族</strong>：兽族中较为新兴的种族，体格偏小，整族全雌，学习能力强，与狼族有深厚的友谊。</li></ul><h3 id="其他独立种族" tabindex="-1">其他独立种族 <a class="header-anchor" href="#其他独立种族" aria-label="Permalink to &quot;其他独立种族&quot;">​</a></h3><ul><li><strong>甲族</strong>：非毛系种族，生存习性与其他种族差异极大，如今近乎灭绝。</li><li><strong>精灵族</strong>：唯一长得像人的种族，尖耳朵、白袍与法杖是其特征。</li></ul><h2 id="种族格局" tabindex="-1">种族格局 <a class="header-anchor" href="#种族格局" aria-label="Permalink to &quot;种族格局&quot;">​</a></h2><h3 id="现存主要种族" tabindex="-1">现存主要种族 <a class="header-anchor" href="#现存主要种族" aria-label="Permalink to &quot;现存主要种族&quot;">​</a></h3><ul><li><strong>三大主族</strong>：鹿、熊、狼——当今的三个主要种族，作为世界三极，都具有强大且独立的种族实力，是当今世界舞台之上毫无疑问的主角。</li><li><strong>其余副族</strong>：狐、兔、鹰、鸽、蜥等，多在黑暗时代前后登上历史舞台。</li><li><strong>传说种</strong>：龙、猫、焰种——是否仍存于世并不确定，往往十分独特且强大。</li></ul><h3 id="已亡种族" tabindex="-1">已亡种族 <a class="header-anchor" href="#已亡种族" aria-label="Permalink to &quot;已亡种族&quot;">​</a></h3><p>猪族、蝠族、鼠族、虎族、豹族——已在历史中彻底消亡。</p><h3 id="流亡-丧失主权的种族" tabindex="-1">流亡/丧失主权的种族 <a class="header-anchor" href="#流亡-丧失主权的种族" aria-label="Permalink to &quot;流亡/丧失主权的种族&quot;">​</a></h3><p>牛族、羊族——或因迁徙而流亡，或已丧失主权。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./种族/">种族设定索引</a></li><li><a href="./种族/五大主族总览">五大主族总览</a></li><li><a href="./历史/">表层历史</a></li><li><a href="./地理/">地理环境</a></li></ul>',23)])])}const g=t(o,[["render",i]]);export{q as __pageData,g as default};
